library(tidyverse)
library(Lahman)


Batting |&gt;
  group_by(playerID) |&gt;
  summarize(
    career_HR = sum(HR, na.rm = TRUE),
    first_year = min(yearID, na.rm = TRUE),
    last_year = max(yearID, na.rm = TRUE)
  ) |&gt;
  arrange(desc(career_HR)) |&gt;
  head(15) |&gt;
  left_join(People, by = "playerID") |&gt;
  mutate(
    name = paste(nameFirst, nameLast),
    span = paste(first_year, last_year, sep = "-"),
    steroid_era = last_year &gt;= 1994 & first_year &lt;= 2009
  ) |&gt;
  ggplot(aes(x = career_HR, y = reorder(name, career_HR), fill = steroid_era)) +
  geom_col() +
  labs(
    title = "Top 15 All-Time Home Run Leaders",
    x = "Career Home Runs",
    y = NULL,
    fill = "Active 1994-2009",
    caption = "Source: Lahman Baseball Database"
  )









Batting |&gt;
  left_join(People, by = "playerID") |&gt;
  filter(nameFirst == "Barry", nameLast == "Bonds") |&gt;
  ggplot(aes(x = yearID, y = HR)) +
  geom_col() +
  labs(
    title = "Barry Bonds Home Runs by Season",
    x = "Season",
    y = "Home Runs",
    caption = "Source: Lahman Baseball Database"
  )

library(tidyverse)
library(Lahman)


hr_by_season &lt;- Teams |&gt;
  group_by(yearID) |&gt;
  summarize(
    total_HR = sum(HR, na.rm = TRUE),
    total_G = sum(G, na.rm = TRUE)
  ) |&gt;
  mutate(
    hr_per_game = total_HR / total_G,
    season_type = if_else(yearID %in% c(1918, 1919, 1981, 1994, 1995, 2020), "Shortened", "Full")
  )


hr_by_season |&gt;
  ggplot(aes(x = yearID, y = hr_per_game)) +
  geom_line(color = "darkgray") +
  geom_point(aes(color = season_type)) +
  labs(
    title = "Home Runs per Game in Major League Baseball by Season",
    x = "Season",
    y = "Home Runs per Game",
    color = "Season Type",
    caption = "Source: Lahman Baseball Database"
  )









Teams |&gt;
  filter(yearID %in% c(1981, 1994, 2019, 2020)) |&gt;
  group_by(yearID) |&gt;
  summarize(
    total_HR = sum(HR, na.rm = TRUE),
    total_G = sum(G, na.rm = TRUE)
  ) |&gt;
  mutate(hr_per_game = total_HR / total_G)

